namespace CheckoutPricing.Domain;

public static class LoyaltyDiscount
{
    private const int CeilingPoints = 10;

    public static int PayableTotalCents(LoyaltyTier tier, int subtotalCents)
    {
        var points = Math.Min(BasePoints(tier) + SizeBonusPoints(subtotalCents), CeilingPoints);
        var discountCents = (long)subtotalCents * points / 100;
        return subtotalCents - (int)discountCents;
    }

    private static int BasePoints(LoyaltyTier tier) => tier switch
    {
        LoyaltyTier.Bronze => 5,
        LoyaltyTier.Silver => 7,
        LoyaltyTier.Gold => 9,
        _ => throw new ArgumentOutOfRangeException(nameof(tier))
    };

    private static int SizeBonusPoints(int subtotalCents) => subtotalCents switch
    {
        >= 20000 => 3,
        >= 5000 => 1,
        _ => 0
    };
}
E
